package com.skillbridge;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.net.URI;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
class WorkspaceService {
 final JdbcTemplate db;final ObjectMapper json;
 WorkspaceService(JdbcTemplate d,ObjectMapper j){db=d;json=j;}
 public JdbcTemplate db(){return db;}
 public ObjectMapper json(){return json;}
 ObjectNode object(String data){try{return (ObjectNode)json.readTree(data);}catch(Exception e){throw new IllegalStateException(e);}}
 String encode(Object data){try{return json.writeValueAsString(data);}catch(Exception e){throw new IllegalArgumentException(e);}}
 ObjectNode newState(String name,String email){var n=json.createObjectNode();n.put("name",name);n.put("email",email);n.put("bio","");n.put("goal","Find my next career step");n.put("level","Beginner");n.put("weeklyGoal",5);n.put("mentorPrice",45);for(String key:List.of("skills","interests","enrolled","saved","started","portfolio","notifications","availability"))n.putArray(key);n.putObject("completed");n.putObject("lessonDates");n.putNull("application");return n;}
 void create(long user,String name,String email){db.update("INSERT INTO workspace(user_id,data) VALUES(?,?::jsonb)",user,encode(newState(name,email)));}
 ObjectNode raw(long user,boolean lock){var s=db.queryForList("SELECT data::text FROM workspace WHERE user_id=?"+(lock?" FOR UPDATE":""),String.class,user);if(s.isEmpty())throw ApiException.error(404,"Workspace not found.");return object(s.get(0));}
 ObjectNode patch(long user,Consumer<ObjectNode> change){var state=raw(user,true);change.accept(state);db.update("UPDATE workspace SET data=?::jsonb,updated_at=now() WHERE user_id=?",encode(state),user);return state;}
 void note(long user,String text){patch(user,s->{var notes=(ArrayNode)s.withArray("notifications");var next=json.createArrayNode();next.add(json.createObjectNode().put("text",text).put("read",false));notes.forEach(next::add);s.set("notifications",next);});}
 void audit(long actor,String action,String target,Object detail){db.update("INSERT INTO audit_event(actor_id,action,target,detail) VALUES(?,?,?,?::jsonb)",actor,action,target,encode(detail));}
 ObjectNode state(SecurityConfig.Member member){long user=member.id();var n=raw(user,false);var bookings=db.queryForList("SELECT b.*,m.user_id AS mentor_user_id,m.name AS mentor_name,u.name AS learner_name FROM booking b JOIN mentor_profile m ON m.id=b.mentor_id JOIN app_user u ON u.id=b.learner_id WHERE "+(member.role().equals("ADMIN")?"true":member.role().equals("MENTOR")?"m.user_id=?":"b.learner_id=?")+" ORDER BY b.starts_at",member.role().equals("ADMIN")?new Object[]{}:new Object[]{user});var list=n.putArray("bookings");for(var b:bookings){var item=json.createObjectNode();item.put("id",b.get("id").toString());item.put("mentorId",((Number)b.get("mentor_id")).longValue());item.put("time",((java.sql.Timestamp)b.get("starts_at")).toInstant().toString());item.put("status",(String)b.get("status"));item.put("price",((Number)b.get("price")).doubleValue());item.put("learnerId",((Number)b.get("learner_id")).longValue());item.put("learnerName",b.get("learner_name").toString());item.put("mentorName",b.get("mentor_name").toString());list.add(item);}
  var messages=n.putArray("messages");var rows=db.queryForList("SELECT msg.*,b.mentor_id,b.learner_id FROM message msg JOIN booking b ON b.id=msg.booking_id JOIN mentor_profile m ON m.id=b.mentor_id WHERE (b.learner_id=? OR m.user_id=?) ORDER BY msg.created_at",user,user);for(var m:rows){var a=json.createObjectNode().put("mentorId",((Number)m.get("mentor_id")).longValue()).put("text",(String)m.get("body")).put("from",Objects.equals(m.get("sender_id"),m.get("learner_id"))?"learner":"mentor").put("time",((java.sql.Timestamp)m.get("created_at")).toInstant().toString()).put("learnerId",((Number)m.get("learner_id")).longValue());messages.add(a);}
  var apps=db.queryForList("SELECT * FROM mentor_application WHERE "+(member.role().equals("ADMIN")?"true":"user_id=?")+" ORDER BY created_at DESC LIMIT 1",member.role().equals("ADMIN")?new Object[]{}:new Object[]{user});if(!apps.isEmpty()){var a=apps.get(0);var app=object(a.get("data").toString());app.put("status",(String)a.get("status"));app.put("id",((Number)a.get("id")).longValue());app.put("userId",((Number)a.get("user_id")).longValue());if(a.get("decision")!=null)app.put("decision",a.get("decision").toString());n.set("application",app);}else n.putNull("application");
  if(member.role().equals("MENTOR")){var profiles=db.queryForList("SELECT id,price FROM mentor_profile WHERE user_id=?",user);if(!profiles.isEmpty()){var profile=profiles.get(0);n.put("mentorPrice",((Number)profile.get("price")).doubleValue());var availability=n.putArray("availability");db.query("SELECT starts_at FROM mentor_slot WHERE mentor_id=? AND starts_at>now() ORDER BY starts_at",(rs,row)->rs.getTimestamp(1).toInstant().toString(),profile.get("id")).forEach(availability::add);}}
  return n;
 }
 JsonNode content(String kind,int id){var found=db.queryForList("SELECT data::text FROM content WHERE kind=? AND data->>'id'=? AND status='Published'",String.class,kind,String.valueOf(id));if(found.isEmpty())throw ApiException.error(404,"Published content not found.");return object(found.get(0));}
 static String text(JsonNode node,String key,int min,int max){String v=node.path(key).asText("").trim();if(v.length()<min||v.length()>max)throw ApiException.error(400,key+" must contain "+min+"–"+max+" characters.");return v;}
 static void safeUrl(String v){if(v.isBlank())return;try{var uri=URI.create(v);if(!List.of("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();}catch(Exception e){throw ApiException.error(400,"Use a complete http or https URL.");}}
 static void stringArray(JsonNode n,int max){if(!n.isArray()||n.size()>max)throw ApiException.error(400,"Please check the selected values.");n.forEach(x->{if(!x.isTextual()||x.asText().length()>100)throw ApiException.error(400,"Invalid selected value.");});}
 ObjectNode profile(SecurityConfig.Member u,JsonNode body){String name=text(body,"name",2,80),goal=text(body,"goal",2,200),bio=text(body,"bio",0,1000),level=text(body,"level",1,20);if(!List.of("Beginner","Intermediate","Advanced").contains(level))throw ApiException.error(400,"Choose a valid experience level.");stringArray(body.path("skills"),30);stringArray(body.path("interests"),20);String avatar=body.path("avatar").asText("");if(avatar.length()>700000||(!avatar.isEmpty()&&!avatar.matches("^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$")))throw ApiException.error(400,"Choose a valid profile image under 500 KB.");db.update("UPDATE app_user SET name=? WHERE id=?",name,u.id());patch(u.id(),s->{s.put("name",name);s.put("goal",goal);s.put("bio",bio);s.put("level",level);s.set("skills",body.get("skills"));s.set("interests",body.get("interests"));s.put("avatar",avatar);});return state(u);}
 ObjectNode enroll(SecurityConfig.Member u,int course){var courseData=content("Course",course);var current=raw(u.id(),true);for(var prereq:courseData.path("prerequisites")){var required=content("Course",prereq.asInt());if(current.path("completed").path(prereq.asText()).size()<required.path("lessons").size())throw ApiException.error(400,"Complete the course prerequisites before enrolling.");}patch(u.id(),s->{var a=s.withArray("enrolled");if(!contains(a,course))a.add(course);});audit(u.id(),"course.enroll",String.valueOf(course),Map.of());return state(u);}
 static boolean contains(JsonNode arr,int id){for(var x:arr)if(x.asInt()==id)return true;return false;}
 ObjectNode lesson(SecurityConfig.Member u,int course,int index){var c=content("Course",course);if(index<0||index>=c.path("lessons").size())throw ApiException.error(400,"Lesson not found.");patch(u.id(),s->{if(!contains(s.path("enrolled"),course))throw ApiException.error(403,"Enroll before completing lessons.");var completed=s.with("completed");String key=String.valueOf(course);var lessons=completed.has(key)?(ArrayNode)completed.get(key):completed.putArray(key);if(!contains(lessons,index)){lessons.add(index);s.with("lessonDates").put(course+":"+index,Instant.now().toString());}});return state(u);}
 ObjectNode start(SecurityConfig.Member u,int id){content("Project",id);patch(u.id(),s->{if(!contains(s.path("started"),id))s.withArray("started").add(id);});return state(u);}
 ObjectNode portfolio(SecurityConfig.Member u,JsonNode p){int id=p.path("id").asInt();var project=content("Project",id);String title=text(p,"title",2,120),description=text(p,"description",20,3000);for(String key:List.of("repository","demo","screenshot"))safeUrl(text(p,key,0,2000));patch(u.id(),s->{if(!contains(s.path("started"),id))throw ApiException.error(400,"Start this project before adding it to your portfolio.");var list=json.createArrayNode();s.withArray("portfolio").forEach(x->{if(x.path("id").asInt()!=id)list.add(x);});var item=json.createObjectNode().put("id",id).put("title",title).put("description",description).put("repository",p.path("repository").asText()).put("demo",p.path("demo").asText()).put("screenshot",p.path("screenshot").asText());item.set("skills",project.path("skills"));list.add(item);s.set("portfolio",list);});audit(u.id(),"portfolio.publish",String.valueOf(id),Map.of());return state(u);}
 ObjectNode book(SecurityConfig.Member u,JsonNode p){if(!u.role().equals("LEARNER"))throw ApiException.error(403,"Learner accounts can book sessions.");int mentor=p.path("mentorId").asInt();Instant start=Instant.parse(text(p,"time",1,60));UUID key=UUID.fromString(text(p,"idempotencyKey",36,36));db.queryForList("SELECT id FROM app_user WHERE id=? FOR UPDATE",u.id());var prior=db.queryForList("SELECT id FROM booking WHERE learner_id=? AND idempotency_key=?",u.id(),key);if(!prior.isEmpty())return state(u);if(start.isBefore(Instant.now()))throw ApiException.error(400,"Choose a future time.");var profiles=db.queryForList("SELECT * FROM mentor_profile m WHERE id=? AND approved AND (user_id IS NULL OR EXISTS(SELECT 1 FROM app_user u WHERE u.id=m.user_id AND u.enabled)) FOR UPDATE",mentor);if(profiles.isEmpty())throw ApiException.error(404,"Approved mentor not found.");if(db.queryForObject("SELECT count(*) FROM mentor_slot WHERE mentor_id=? AND starts_at=?",Long.class,mentor,java.sql.Timestamp.from(start))==0)throw ApiException.error(409,"That time is not available. Please choose a published slot.");if(db.queryForObject("SELECT count(*) FROM booking WHERE status='confirmed' AND (mentor_id=? OR learner_id=?) AND starts_at>? AND starts_at<?",Long.class,mentor,u.id(),java.sql.Timestamp.from(start.minusSeconds(2700)),java.sql.Timestamp.from(start.plusSeconds(2700)))>0)throw ApiException.error(409,"There is a conflicting session. Please choose another time.");UUID id=UUID.randomUUID();Object price=profiles.get(0).get("price");db.update("INSERT INTO booking(id,learner_id,mentor_id,starts_at,price,idempotency_key) VALUES(?,?,?,?,?,?)",id,u.id(),mentor,java.sql.Timestamp.from(start),price,key);db.update("INSERT INTO payment(id,booking_id,provider,status,amount) VALUES(?,?,'internal_development_sandbox','test_paid',?)",UUID.randomUUID(),id,price);audit(u.id(),"payment.test_paid",id.toString(),Map.of("amount",price,"sandbox",true));note(u.id(),"Session confirmed. Development sandbox payment recorded; no real money charged.");return state(u);}
 ObjectNode cancel(SecurityConfig.Member u,UUID id){var rows=db.queryForList("SELECT b.*,m.user_id AS mentor_user FROM booking b JOIN mentor_profile m ON m.id=b.mentor_id WHERE b.id=? FOR UPDATE OF b",id);if(rows.isEmpty())throw ApiException.error(404,"Booking not found.");var b=rows.get(0);if(!Objects.equals(b.get("learner_id"),u.id())&&!Objects.equals(b.get("mentor_user"),u.id())&&!u.role().equals("ADMIN"))throw ApiException.error(403,"You cannot access this booking.");if(!b.get("status").equals("cancelled")){db.update("UPDATE booking SET status='cancelled' WHERE id=?",id);db.update("UPDATE payment SET status='test_refunded' WHERE booking_id=? AND status='test_paid'",id);audit(u.id(),"booking.cancel_and_test_refund",id.toString(),Map.of("sandbox",true));note(((Number)b.get("learner_id")).longValue(),"Your session was cancelled. A test refund was recorded.");}return state(u);}
 ObjectNode message(SecurityConfig.Member u,JsonNode p){String body=text(p,"text",1,2000);int mentor=p.path("mentorId").asInt();Long learner=p.has("learnerId")?p.path("learnerId").asLong():u.id();var ids=db.queryForList("SELECT b.id FROM booking b JOIN mentor_profile m ON m.id=b.mentor_id WHERE b.mentor_id=? AND b.learner_id=? AND b.status='confirmed' AND (b.learner_id=? OR m.user_id=?) ORDER BY b.created_at DESC LIMIT 1",UUID.class,mentor,learner,u.id(),u.id());if(ids.isEmpty())throw ApiException.error(403,"An active booking with this mentor is required.");db.update("INSERT INTO message(booking_id,sender_id,body) VALUES(?,?,?)",ids.get(0),u.id(),body);return state(u);}
 ObjectNode apply(SecurityConfig.Member u,JsonNode body){var data=json.createObjectNode().put("name",text(body,"name",2,80)).put("expertise",text(body,"expertise",2,200)).put("experience",text(body,"experience",30,3000)).put("documents",text(body,"documents",1,2000));safeUrl(data.path("documents").asText());db.update("INSERT INTO mentor_application(user_id,data) VALUES(?,?::jsonb) ON CONFLICT(user_id) DO UPDATE SET data=excluded.data,status='Pending',decision=NULL,reviewed_by=NULL,reviewed_at=NULL",u.id(),encode(data));note(u.id(),"Your mentor application is ready for review.");audit(u.id(),"mentor.apply",String.valueOf(u.id()),Map.of());return state(u);}
 ObjectNode availability(SecurityConfig.Member u,JsonNode p){var ids=db.queryForList("SELECT id FROM mentor_profile WHERE user_id=? AND approved FOR UPDATE",Long.class,u.id());if(ids.isEmpty())throw ApiException.error(403,"Approval is required before publishing mentor availability.");long id=ids.get(0);double price=p.path("price").asDouble(-1);if(price<0||price>1000||!p.path("slots").isArray()||p.path("slots").size()>100)throw ApiException.error(400,"Check your price and available times.");db.update("DELETE FROM mentor_slot WHERE mentor_id=?",id);for(var t:p.path("slots")){var time=Instant.parse(t.asText());if(time.isBefore(Instant.now()))throw ApiException.error(400,"Only future availability can be published.");db.update("INSERT INTO mentor_slot VALUES(?,?) ON CONFLICT DO NOTHING",id,java.sql.Timestamp.from(time));}db.update("UPDATE mentor_profile SET price=? WHERE id=?",price,id);patch(u.id(),s->{s.set("availability",p.get("slots"));s.put("mentorPrice",price);});return state(u);}
}
